    status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: false, hasUpstream: false }, valid: true,
}

function agentConversation(overrides: Partial<AgentConversation> = {}): AgentConversation {
    return {
        actionId: 'respond',
