            </ResizablePopper>,
        )

        expect(document.querySelector('.MuiPopper-root')).toHaveStyle({ position: 'fixed' })
    })

    it('resizes and closes with Escape', () => {
        const onClose = vi.fn()
        render(
            <ResizablePopper
                anchorElement={document.body}
                initialSize={{ height: 300, width: 400 }}
                labelId="popper-title"
